function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');toastTimer=2.2}
function startGame(){document.getElementById('intro').classList.add('hidden');document.getElementById('end').classList.add('hidden');document.getElementById('hud').style.display='block';active=true;ended=false;last=performance.now();requestAnimationFrame(loop);}
document.getElementById('start').onclick=startGame;document.getElementById('again').onclick=()=>{location.reload()};
addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!active)return;if(e.code==='KeyE')scavenge();if(e.code==='KeyR')useMed();if(e.code==='Digit1')setWeapon(0);if(e.code==='Digit2')setWeapon(1);if(e.code==='Digit3')setWeapon(2);if(e.code==='KeyF')shoot();if(e.code==='Space')attack();});addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('pointerdown',()=>{if(active&&player.weapon===1)shoot();else if(active)attack()});
function setWeapon(n){player.weapon=n;document.querySelectorAll('.slot').forEach((el,i)=>el.classList.toggle('active',i===n))}
function getMove(){let x=0,y=0;if(keys.KeyA||keys.ArrowLeft)x--;if(keys.KeyD||keys.ArrowRight)x++;if(keys.KeyW||keys.ArrowUp)y--;if(keys.KeyS||keys.ArrowDown)y++;x+=moveX;y+=moveY;const m=Math.hypot(x,y);if(m>1){x/=m;y/=m}return{x,y}}
function collides(x,y,r){for(const b of buildings){let cx=Math.max(b.x,Math.min(x,b.x+b.w)),cy=Math.max(b.y,Math.min(y,b.y+b.h));if((x-cx)**2+(y-cy)**2<r*r)return true}return false}
function moveEntity(ent,dx,dy,r){if(!collides(ent.x+dx,ent.y,r))ent.x+=dx;if(!collides(ent.x,ent.y+dy,r))ent.y+=dy;ent.x=Math.max(15,Math.min(world.w-15,ent.x));ent.y=Math.max(15,Math.min(world.h-15,ent.y))}
function scavenge(){let nearest=null,dist=62;for(const item of loot){if(item.taken)continue;const d=Math.hypot(item.x-player.x,item.y-player.y);if(d<dist){dist=d;nearest=item}}if(!nearest){toast('NOTHING WITHIN REACH');return}nearest.taken=true;switch(nearest.type){case'food':player.hunger=Math.min(100,player.hunger+27);toast('CANNED PEACHES · HUNGER RESTORED');break;case'water':player.thirst=Math.min(100,player.thirst+32);toast('BOTTLED WATER · THIRST RESTORED');break;case'ammo':player.ammo+=5;toast('5 ROUNDS · .38 SPECIAL');break;case'med':player.meds++;toast('MEDKIT FOUND · PRESS R TO USE');break;case'scrap':toast('A USELESS RELIC. KEEP MOVING.');break}updateHud()}
function useMed(){if(player.meds<1){toast('NO MEDKITS');return}if(player.hp>=100){toast('VITALS ALREADY STABLE');return}player.meds--;player.hp=Math.min(100,player.hp+45);toast('FIELD DRESSING APPLIED · +45 VITALS');updateHud()}
function attack(){if(player.attack>0)return;player.attack=.34;shake=3;let hits=0;for(const z of zombies){let dx=z.x-player.x,dy=z.y-player.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx),delta=Math.atan2(Math.sin(a-player.dir),Math.cos(a-player.dir));if(d<66&&Math.abs(delta)<1.1){z.hp-=38;z.stun=.22;hits++;for(let n=0;n<5;n++)particles.push({x:z.x,y:z.y,vx:rr(-60,60),vy:rr(-60,60),life:.4,color:'#a95040'})}}if(hits)toast(hits>1?'THE HATCHET BITES DEEP':'HIT CONFIRMED');}
function shoot(){if(player.weapon!==1&&keys.KeyF===false){setWeapon(1)}if(player.ammo<=0){toast('CLICK · EMPTY CHAMBER');return}player.ammo--;player.attack=.18;shake=5;let best=null,bd=410;for(const z of zombies){let dx=z.x-player.x,dy=z.y-player.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx),del=Math.atan2(Math.sin(a-player.dir),Math.cos(a-player.dir));if(d<bd&&Math.abs(del)<.17){best=z;bd=d}}bullets.push({x:player.x+Math.cos(player.dir)*16,y:player.y+Math.sin(player.dir)*16,a:player.dir,life:.35});if(best){best.hp-=65;best.stun=.2;for(let n=0;n<7;n++)particles.push({x:best.x,y:best.y,vx:rr(-90,90),vy:rr(-90,90),life:.45,color:'#b95645'})}updateHud()}
