function update(dt){frame++;gameElapsed+=dt;time-=dt;if(time<=0){finish(true);return}let {x,y}=getMove();sprinting=!!(keys.ShiftLeft||keys.ShiftRight)&&player.stamina>2&&(x||y);let sp=player.speed*(sprinting?1.55:1);player.stamina=Math.max(0,Math.min(100,player.stamina+(sprinting?-32:18)*dt));if(x||y){player.dir=Math.atan2(y,x);moveEntity(player,x*sp*dt,y*sp*dt,player.r)}player.attack=Math.max(0,player.attack-dt);player.invuln=Math.max(0,player.invuln-dt);player.hunger=Math.max(0,player.hunger-dt*.17);player.thirst=Math.max(0,player.thirst-dt*.27);if(player.hunger<=0||player.thirst<=0)player.hp-=dt*.8;if(player.hp<=0){finish(false);return}
if(Math.random()<dt*(.17+Math.min(.25,gameElapsed/500)))spawnZombie();for(const z of zombies){if(z.hp<=0)continue;z.stun=Math.max(0,z.stun-dt);z.attack=Math.max(0,z.attack-dt);let dx=player.x-z.x,dy=player.y-z.y,d=Math.hypot(dx,dy);if(!z.stun&&d>21){moveEntity(z,dx/d*z.speed*dt,dy/d*z.speed*dt,z.r);z.wander-=dt}if(d<28&&z.attack<=0&&player.invuln<=0){z.attack=1.15;player.hp-=9;player.invuln=.45;shake=7;toast('INFECTED ATTACK · MOVE!')}}for(let i=zombies.length-1;i>=0;i--){if(zombies[i].hp<=0){kills++;if(Math.random()<.14)loot.push({x:zombies[i].x,y:zombies[i].y,type:Math.random()<.5?'ammo':'food',taken:false,glow:0});zombies.splice(i,1)}}for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}for(let i=bullets.length-1;i>=0;i--){bullets[i].life-=dt;if(bullets[i].life<=0)bullets.splice(i,1)}
